def transform(grid):
    h, w = len(grid), len(grid[0])
    key = None

    # Find the repeated horizontal strip used as the color sequence.
    for r in range(h - 1):
        if grid[r] != grid[r + 1]:
            continue
        vals = [c for c, v in enumerate(grid[r]) if v != 0]
        if vals and vals == list(range(vals[0], vals[-1] + 1)):
            seq = grid[r][vals[0]:vals[-1] + 1]
            if len(seq) >= 2 and len(set(seq)) >= 2:
                end = r + 1
                while end + 1 < h and grid[end + 1] == grid[r]:
                    end += 1
                key = ("rows", r, end, vals[0], vals[-1], seq)
                break

    # Also allow a repeated vertical strip.
    if key is None:
        for c in range(w - 1):
            col = [grid[r][c] for r in range(h)]
            next_col = [grid[r][c + 1] for r in range(h)]
            if col != next_col:
                continue
            vals = [r for r, v in enumerate(col) if v != 0]
            if vals and vals == list(range(vals[0], vals[-1] + 1)):
                seq = col[vals[0]:vals[-1] + 1]
                if len(seq) >= 2 and len(set(seq)) >= 2:
                    end = c + 1
                    while end + 1 < w and [grid[r][end + 1] for r in range(h)] == col:
                        end += 1
                    key = ("cols", vals[0], vals[-1], c, end, seq)
                    break

    if key is None:
        return [row[:] for row in grid]

    seq = key[-1]
    excluded = set()
    if key[0] == "rows":
        _, r0, r1, c0, c1, _ = key
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                excluded.add((r, c))
    else:
        _, r0, r1, c0, c1, _ = key
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                excluded.add((r, c))

    # Locate a colored shape outside the key strip.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in excluded or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in excluded and
                            (nr, nc) not in seen and
                            grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if color in seq:
                components.append((len(comp), color, comp))

    if not components:
        return [row[:] for row in grid]

    _, anchor_color, comp = max(components, key=lambda x: x[0])
    min_r = min(r for r, c in comp)
    min_c = min(c for r, c in comp)
    max_r = max(r for r, c in comp)
    max_c = max(c for r, c in comp)
    shape = {(r - min_r, c - min_c) for r, c in comp}
    shape_h = max_r - min_r + 1
    anchor_index = seq.index(anchor_color)
    start_r = min_r - anchor_index * shape_h

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(seq):
        top = start_r + i * shape_h
        for dr, dc in shape:
            rr, cc = top + dr, min_c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
